Cho đoạn chương trình sau:
def loc_chuoi(s, buoc=2):
    kq = ""
    for i in range(0, len(s), buoc):
        if s[i].isupper(): kq += s[i].lower()
        else: kq += s[i].upper()
    return kq
print(loc_chuoi("PyThOn"))
